// --- YENİ E-POSTA BULMA VE TEMİZLEME FONKSİYONU ---
/**
 * Verilen 'lead' nesnesi içinde geçerli bir e-posta adresi arar, bulur ve temizler.
 * 'mail' kelimesini içeren tüm alanları kontrol eder (örn: email, email1, manager_mail1).
 * Birden fazla '@' içeren hatalı e-postaları (örn: 'a@b@c.com') düzelterek 'b@c.com' formatına getirir.
 * @param {object} leadObject - Potansiyel e-posta alanlarını içeren nesne.
 * @returns {string|null} - Bulunan ve temizlenen ilk geçerli e-posta adresini veya bulunamazsa null döner.
 */
const findAndCleanEmail = (leadObject) => {
    // Genel e-posta formatını kontrol eden basit bir regex.
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

    // 'lead' nesnesindeki tüm anahtarları al.
    const keys = Object.keys(leadObject);

    // İçinde 'mail' geçen anahtarları bul (büyük/küçük harf duyarsız).
    const emailKeys = keys.filter(key => key.toLowerCase().includes('mail'));
    // 'email' anahtarını da ekleyerek önceliklendir
    if (!emailKeys.includes('email')) emailKeys.unshift('email');


    // Potansiyel e-posta anahtarları arasında dolaşarak ilk geçerli olanı bul.
    for (const key of emailKeys) {
        let potentialEmail = leadObject[key];

        if (potentialEmail && typeof potentialEmail === 'string') {
            potentialEmail = potentialEmail.trim();
            const atCount = (potentialEmail.match(/@/g) || []).length;

            if (atCount > 1) {
                // Eğer birden fazla '@' varsa, e-postayı yeniden oluştur.
                // Örnek: 'info@tcm.zentrum.lev@gmx.de' -> 'tcm.zentrum.lev@gmx.de'
                const parts = potentialEmail.split('@');
                const correctedEmail = parts.slice(-2).join('@');
                if (emailRegex.test(correctedEmail)) {
                    return correctedEmail; // İlk geçerli ve düzeltilmiş e-postayı döndür.
                }
            } else if (atCount === 1) {
                // Eğer tek '@' varsa, sadece geçerliliğini kontrol et.
                if (emailRegex.test(potentialEmail)) {
                    return potentialEmail; // İlk geçerli e-postayı döndür.
                }
            }
        }
    }

    return null; // Geçerli bir e-posta bulunamazsa null döndür.
};


