const allLeads = $('MySQL (Fetch All Doctor Leads)').all();
const warmLeadData = $('MySQL (Fetch Warm Lead CIDs)').all();

// Warm CID'leri hızlı arama için bir Set'e dönüştür
const warmCidSet = new Set(warmLeadData.map(item => item.json.cid));

const results = [];
for (const leadItem of allLeads) {
  const isWarm = warmCidSet.has(leadItem.json.cid);
  leadItem.json.is_warm = isWarm;
  results.push(leadItem);
}

return results;

// Önceki node'dan gelen JSON verisi
const input = $json;

// Temizlenecek e-posta alanlarının listesi
const emailFields = [
  'email',
  'email1',
  'manager_mail1',
  'manager_mail2',
  'manager_mail3'
];

// Her bir e-posta alanını kontrol et ve "(at)" ifadesini "@" ile değiştir
for (const field of emailFields) {
  const value = input[field];
  if (value && typeof value === 'string') {
    input[field] = value.replace(/\(at\)/gi, '@');
  }
}

// Güncellenmiş JSON verisini çıktıya aktar
return [
  {
    json: input
  }
];

// Önceki düğümden gelen lead verisini al
const lead = $("Set (Current Lead Data)").first().json

let firstNameForAI = 'unknown'; // AI'ya gönderilecek ilk isim
let emailForAI = null;         // AI'ya gönderilecek e-posta (eğer gerekirse)

// 1. manager1 alanını kontrol et
if (lead.manager1 && typeof lead.manager1 === 'string' && lead.manager1.trim() !== '') {
    const parts = lead.manager1.trim().split(' ');
    if (parts.length > 0) {
        firstNameForAI = parts[0];
    }
}

// 2. Eğer manager1'den isim bulunamadıysa, name alanını kontrol et
if (firstNameForAI === 'unknown' && lead.name && typeof lead.name === 'string' && lead.name.trim() !== '') {
    const parts = lead.name.trim().split(' ');
    if (parts.length > 0) {
        firstNameForAI = parts[0];
    }
}

// E-posta adresini temizle ve hazırla (eğer AI'ya göndermek isterseniz)
// Bu kısım, AI'dan e-posta doğrulaması veya analizi isterseniz kullanılabilir.
// Şu anki cinsiyet çıkarımı prompt'u için doğrudan kullanılmayabilir,
// ancak gelecekteki genişletmeler için faydalıdır.
if (lead.email1 && typeof lead.email1 === 'string' && lead.email1.trim() !== '') {
    emailForAI = lead.email1.trim().replace(/\[at\]/gi, '@');
    // Eğer @ işareti yoksa ekleme mantığı burada olabilir,
    // ancak AI'dan e-posta doğrulaması istemiyorsak bu kadar detaya gerek yok.
}

// Sonraki düğüme gönderilecek veriyi hazırla
// Orijinal lead verisini koruyarak, AI için özel alanlar ekliyoruz.
return [{
    json: {
        // Orijinal lead verisini koru (isteğe bağlı, ancak genellikle iyi bir pratiktir)
        ...lead,
        // AI'ya gönderilecek özel alanlar
        firstNameForAI: firstNameForAI,
        emailForAI: emailForAI // Eğer AI'ya e-posta göndermek isterseniz
    }
}];

// Önceki düğümden (HTTP Request - AI Gender Inference) gelen veriyi al
// Bu düğümün çıktısı genellikle tek bir öğe içerir.
const aiResponseItem = $input.first();
const aiResponseJson = aiResponseItem.json; // JSON objesini al

let parsedGenderData = { inferred_gender: 'unknown' }; // Varsayılan değer

// 'response' alanının varlığını ve tipini kontrol et
// AI'dan gelen yanıtın 'response' anahtarı altında bir string olarak geldiğini varsayıyoruz.
if (aiResponseJson.response && typeof aiResponseJson.response === 'string') {
    try {
        // 'response' string'ini JSON objesine dönüştür
        // JSON.parse'dan önce trim() kullanmak, string'in başındaki/sonundaki boşlukları/yeni satırları temizler.
        const rawParsed = JSON.parse(aiResponseJson.response.trim());

        // Eğer parse edilen objede 'inferred_gender' alanı varsa kullan, yoksa 'unknown' olarak kalır.
        if (rawParsed.inferred_gender) {
            parsedGenderData.inferred_gender = rawParsed.inferred_gender;
        }
    } catch (error) {
        // JSON parse hatası durumunda konsola hata yazdır ve varsayılan değeri koru
        console.error("Error parsing AI response JSON:", error);
        // Hata durumunda parsedGenderData zaten varsayılan 'unknown' değerini tutuyor olacak.
    }
}

// Sonraki düğüme gönderilecek veriyi hazırla.
// Bu düğümün çıktısı, sadece parse edilmiş cinsiyet bilgisini içermelidir.
// Diğer lead verileri, Code (Prepare Lead Data for AI) düğümünden veya
// doğrudan Code (Build Instantly Lead Body - Placeholder) düğümünde alınacaktır.
return [{
    json: {
        inferred_gender: parsedGenderData.inferred_gender
    }
}];
